/** UC1-PAUSE-MIRROR + UC1-RESUME-MIRROR tests — TS mirror of hermes
 * `UC1Handoff` (pause beat + resume, `8871dda` + the argv-law fix) riding the
 * consolidated `src/uc1-handoff.ts`.
 *
 * Error reason strings are asserted byte-for-byte (the mirror law); stderr
 * tails that embed host/tool output are prefix-pinned only. The resume
 * valid-snapshot test deep-equals the committed golden fixture
 * `packages/opencode/test/fixtures/uc1-resume-golden.json`, generated by the
 * hermes reference — same fixture, same fields, as the hermes
 * `UC1ResumeGoldenParityTests` (09-plugin-parity.md §4).
 *
 * Fixture discipline: snapshots are built with cwd=repo root and the RELATIVE
 * trace argv `corpus/m1/session-healthy.jsonl` — manifest.yaml/llms.txt embed
 * the trace argv string, so relative keeps artifact bytes host-independent
 * (probed 2026-10-25). Requires the release binaries + the zstd CLI.
 */

import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import { copyFileSync, mkdtempSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { test } from "node:test";

import type { ResumeResult } from "../src/uc1-handoff.ts";
import { pauseTurnFromEnv, resumeVerify, rustBinDir, snapshotDigest, uc1Pause } from "../src/uc1-handoff.ts";

const REPO_ROOT = fileURLToPath(new URL("../../..", import.meta.url));
const ANCHOR = "corpus/m1/session-healthy.jsonl"; // relative argv (fixture discipline)

const GOLDEN_PATH = join(REPO_ROOT, "packages/opencode/test/fixtures/uc1-resume-golden.json");
const GOLDEN = JSON.parse(readFileSync(GOLDEN_PATH, "utf8")) as {
  snapTurn: number;
  verified: boolean;
  reason: string;
  snapshotDigest: string;
  artifactNames: string[];
  manifest: unknown;
  projection: unknown;
  diff: unknown;
};

function freshTmp(label: string): string {
  return mkdtempSync(join(tmpdir(), `ctxvm-b3-${label}-`));
}

function baseName(path: string): string {
  const parts = path.split("/");
  return parts[parts.length - 1] ?? path;
}

function sha256(path: string): string {
  return createHash("sha256").update(readFileSync(path)).digest("hex");
}

function buildGoldenSnapshot(dir: string): void {
  const bin = rustBinDir();
  assert.ok(bin, "release binaries not built — run the cargo build gate");
  const proc = spawnSync(
    join(bin, "export"),
    [ANCHOR, "--turn", "0", "--output", dir, "--odps"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  assert.equal(proc.status, 0, `export failed: ${proc.stderr}`);
}

// ---------------------------------------------------------------------------
// Resume v-next checks (UC1-VERIFY-CHECKS): design §3 (1)(3)(4) in-module
// ---------------------------------------------------------------------------

/** Test helper: rewrite one row's recorded hash in checksums.sha256 so an
 * intentionally re-worded artifact passes row verification and a LATER check
 * becomes reachable. Row format mirrors the emitter: "<hash>  <name>". */
function fixRow(dir: string, name: string, digestHex: string): void {
  const file = join(dir, "checksums.sha256");
  // Test names are fixed literals — dots are the only metacharacters present.
  const nameRe = new RegExp(`^\\s*\\S+\\s+${name.replace(/\./g, "\\.")}\\s*$`);
  const out = readFileSync(file, "utf8").split("\n").map((l) =>
    nameRe.test(l) ? `${digestHex}  ${name}` : l,
  );
  writeFileSync(file, out.join("\n"));
}

test("v-next (1): corrupted artifact byte → verified=False 'checksum mismatch' (the digest hashed only hex strings — both sides disclosed)", () => {
  const dir = freshTmp("vnext-corrupt");
  buildGoldenSnapshot(dir);
  const pt = join(dir, "page-table-0.json");
  writeFileSync(pt, readFileSync(pt, "utf8") + " "); // quiet byte corruption
  const res = resumeVerify(dir);
  assert.deepEqual(res, {
    exit_code: 2,
    verified: false,
    reason: "checksum mismatch for page-table-0.json",
    evidence: { turn: 0, snapshot: dir },
  });
});

