test("pause argv law: turn rides the documented --turn N flag form", () => {
  // (the hermes bare positional was rejected by the real binary — probe).
  const dir = freshTmp("argvlaw");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  const result = uc1Pause({ traceDir: dir, turn: 2 });
  assert.equal(result.exit_code, 0, `export failed: ${result.stderr}`);
  assert.equal(result.verified, true); // counterproof now live (era copy == package slice on this anchor)
  assert.equal(result.diff_relation, "identical"); // era pair canonical — m6 law (UC1-PAUSE-WIRE backfill)
  const snapshotDir = join(dir, "handoff");
  assert.ok(
    Object.keys(result.snapshot).includes("handoff_dir"),
    "snapshot must carry the dir/label/turn bookkeeping",
  );
  assert.equal(result.snapshot.label, "turn-2");
  assert.equal(result.snapshot.turn, 2);
  // the packaged tree exists and carries all five artifacts
  const packaged = Object.keys(result.report as Record<string, unknown>);
  assert.ok(packaged.includes("artifacts"));
  assert.equal(
    ((result.report as Record<string, unknown>).artifacts as unknown[]).length,
    5,
  );
});

