test("pause era copies: cp -n never clobbers; snapshot records paths regardless", () => {
  const dir = freshTmp("era");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "base.jsonl"));
  writeFileSync(join(dir, "base.meta.json"), '{"sidecar": true}\n');
  // pre-existing era files must NOT be clobbered (cp -n law)
  writeFileSync(join(dir, "base-flush.jsonl"), "JUNK-ERA");
  writeFileSync(join(dir, "base-flush.meta.json"), "JUNK-META");
  const result = uc1Pause({ traceDir: dir, handoffName: "base" });
  assert.equal(result.exit_code, 0, result.stderr);
  assert.equal(readFileSync(join(dir, "base-flush.jsonl"), "utf8"), "JUNK-ERA");
  assert.equal(readFileSync(join(dir, "base-flush.meta.json"), "utf8"), "JUNK-META");
  // snapshot still records the era paths (reference quirk: records even when
  // the copy was skipped)
  assert.equal(result.snapshot.jsonl, join(dir, "base-flush.jsonl"));
  assert.equal(result.snapshot["meta.json"], join(dir, "base-flush.meta.json"));
  // export ran on the ORIGINAL base (not the junk era)
  const rep = result.report as Record<string, unknown>;
  const snap = rep.snapshot as Record<string, unknown>;
  assert.equal(snap.sourceEvents, 12);
});

