test("pause packages byte-identical to a direct export run (design §6 B2 TODO closed)", () => {
  const dir = freshTmp("bytecmp");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  const viaPause = uc1Pause({ traceDir: dir, turn: 2 });
  assert.equal(viaPause.exit_code, 0, viaPause.stderr);
  const directDir = join(dir, "direct");
  const bin = rustBinDir();
  assert.ok(bin);
  const direct = spawnSync(
    join(bin, "export"),
    [join(dir, "handoff.jsonl"), "--turn", "2", "--output", directDir, "--odps"],
    { cwd: REPO_ROOT, encoding: "utf8" },
  );
  assert.equal(direct.status, 0, direct.stderr);
  const names = readdirSync(join(dir, "handoff")).sort();
  assert.deepEqual(names, readdirSync(directDir).sort());
  for (const name of names) {
    assert.equal(
      sha256(join(dir, "handoff", name)),
      sha256(join(directDir, name)),
      `artifact mismatch: ${name}`,
    );
  }
});

test("pause witness shape: paused_at/turn/handoff_dir + values-order quirk", () => {
  const dir = freshTmp("witness");
  copyFileSync(join(REPO_ROOT, ANCHOR), join(dir, "handoff.jsonl"));
  writeFileSync(join(dir, "handoff.meta.json"), "{}\n");
  const result = uc1Pause({ traceDir: dir, turn: 2 });
  const wit = result.witness;
  assert.ok(wit);
  assert.ok(wit.paused_at.endsWith("Z"));
  assert.equal(wit.turn, 2);
  assert.equal(wit.handoff_dir, dir);
  // artifacts = the snapshot dict VALUES in insertion order (reference quirk):
  // era copies first, then the snapshot dir, the label, the turn.
  const arts = wit.artifacts as unknown[];
  assert.equal(arts[0], join(dir, "handoff-turn-2.jsonl"));
  assert.equal(arts[1], join(dir, "handoff-turn-2.meta.json"));
  assert.equal(arts[2], join(dir, "handoff"));
  assert.equal(arts[3], "turn-2");
  assert.equal(arts[4], 2);
});

